<?php require dirname(__DIR__).'/bootstrap.php';
if(isset($_POST['logout'])){session_destroy();header('Location: index.php');exit;}if(empty($_SESSION['admin'])){if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals(csrf(),$_POST['csrf']??'')){$q=db()->prepare('SELECT * FROM admins WHERE email=?');$q->execute([strtolower($_POST['email']??'')]);$a=$q->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin']=$a['id'];header('Location: index.php');exit;}$error='Credenciales incorrectas';}?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="../public/assets/css/app.css"><title>Administración</title></head><body><main><form method="post"><h1>Administración</h1><input type="hidden" name="csrf" value="<?=csrf()?>"><p><?=htmlspecialchars($error??'')?></p><label>Correo</label><input type="email" name="email" required><label>Contraseña</label><input type="password" name="password" required><button type="submit">Ingresar</button></form></main></body></html><?php exit;}
$term=trim($_GET['q']??'');$status=$_GET['status']??'';$sql='SELECT * FROM registrations WHERE 1';$params=[];if($term){$sql.=' AND (full_name LIKE ? OR email LIKE ? OR phone LIKE ?)';$params=array_fill(0,3,'%'.$term.'%');}if(in_array($status,['pending','processing','scheduled','failed','canceled','rescheduled'],true)){$sql.=' AND status=?';$params[]=$status;}$sql.=' ORDER BY id DESC LIMIT 500';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$stats=db()->query('SELECT status,COUNT(*) total FROM registrations GROUP BY status')->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../public/assets/css/app.css"><style>table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left;font-size:13px}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{background:#fff;padding:18px;border-radius:10px}.admin-nav{display:flex;gap:12px;margin-bottom:20px}.admin-nav a{color:#044f8c;font-weight:700}</style><title>Inscripciones</title></head><body><main><nav class="admin-nav"><a href="index.php">Resumen</a><a href="inscritos.php">Informes de inscritos</a></nav><div class="cards"><?php foreach($stats as $s):?><div class="card"><b><?=$s['total']?></b> <?=htmlspecialchars($s['status'])?></div><?php endforeach?></div><h1>Inscripciones</h1><form method="get"><input name="q" placeholder="Nombre, correo o celular" value="<?=htmlspecialchars($term)?>"><select name="status"><option value="">Todos los estados</option><?php foreach(['scheduled','failed','canceled','rescheduled'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><button type="submit">Filtrar</button></form><table><thead><tr><th>Nombre</th><th>Correo</th><th>Fecha</th><th>Estado</th><th>Sheets</th><th>Correo enviado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['selected_start_local'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=$r['sheets_synced_at']?'Sí':'Pendiente'?></td><td><?=$r['email_sent_at']?'Sí':'Pendiente'?></td></tr><?php endforeach?></tbody></table><form method="post"><button name="logout">Salir</button></form></main></body></html>
